const fehlerText = (r) => {
  const e = r && r.error;
  if (!e) return '';
  const t = typeof e === 'string' ? e : e.message || JSON.stringify(e);
  if (/authentication_error|invalid x-api-key|invalid_api_key|API key not valid|API_KEY_INVALID|Authorization failed|Unauthorized|Forbidden|\b40[013]\b/i.test(t)) return 'kein gültiger Schlüssel eingetragen';
  if (/ECONNREFUSED|ENOTFOUND|timeout/i.test(t)) return 'nicht erreichbar';
  return t.slice(0, 200);
};
const c = $('Claude: Modellliste').first().json || {};
const claudeModelle = Array.isArray(c.data) ? c.data.filter((m) => m.type === 'model' || !m.type).map((m) => ({ id: m.id, name: m.display_name || m.id, erstellt: m.created_at || '' })) : [];
// OpenAI: nur Chat-Modelle (keine Bild-, Audio-, Embedding-Modelle), neueste zuerst
const oa = $('OpenAI: Modellliste').first().json || {};
const openaiModelle = Array.isArray(oa.data)
  ? oa.data
      .filter((m) => /^(gpt-|o\d|chatgpt-)/.test(m.id) && !/(audio|realtime|tts|transcribe|image|search|embedding|instruct|moderation)/.test(m.id))
      .sort((a, b) => (b.created || 0) - (a.created || 0))
      .map((m) => ({ id: m.id, name: m.id }))
  : [];
// Gemini: nur Modelle, die Text erzeugen können
const ge = $('Gemini: Modellliste').first().json || {};
const geminiModelle = Array.isArray(ge.models)
  ? ge.models
      .filter((m) => /gemini/.test(m.name) && (m.supportedGenerationMethods || []).includes('generateContent') && !/(embedding|image|tts|audio)/.test(m.name))
      .map((m) => ({ id: String(m.name).replace(/^models\//, ''), name: m.displayName || m.name }))
  : [];
// Mistral: nur Chat-Modelle
const mi = $('Mistral: Modellliste').first().json || {};
const mistralModelle = Array.isArray(mi.data)
  ? mi.data
      .filter((m) => !m.capabilities || m.capabilities.completion_chat)
      .sort((a, b) => (b.created || 0) - (a.created || 0))
      .map((m) => ({ id: m.id, name: m.name || m.id }))
  : [];
const eintrag = (liste, roh) => ({ ok: liste.length > 0, modelle: liste, fehler: liste.length ? '' : fehlerText(roh) || 'kein Schlüssel eingetragen' });
return [
  {
    json: {
      abgefragt_am: new Date().toISOString(),
      anbieter: {
        claude: eintrag(claudeModelle, c),
        openai: eintrag(openaiModelle, oa),
        gemini: eintrag(geminiModelle, ge),
        mistral: eintrag(mistralModelle, mi),
      },
    },
  },
];
